/** Generated from real offline Blender Mantaflow R06 VDB. No realtime fluid claim. */
export const MIST_CACHE_SHAPE = [40,32,40] as const;
export const MIST_CACHE_PERIOD=6;
export const MIST_CACHE_SOURCE_SHA="28067c759001b40570465d5a457337af0a02f03bcbb13f156107f5cea0b24ed3";
const encoded=["","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""];
const frames=encoded.map(s=>{const raw=atob(s),a=new Uint8Array(40*32*40);let p=0;for(let i=0;i<raw.length;i+=2){const n=raw.charCodeAt(i);a.fill(raw.charCodeAt(i+1),p,p+n);p+=n;}if(p!==a.length)throw new Error('mist cache RLE length');return a;});
export function mantaMistDensity(time:number,phase:number,mirror=false){
 const t=((time+phase)%6+6)%6,f=t*8,lo=Math.min(frames.length-2,Math.floor(f)),mix=f-lo,a=frames[lo],b=frames[lo+1],out=new Uint8Array(a.length);
 const wrap=Math.max(0,(t-5.5)/.5);
 for(let z=0;z<40;z++)for(let y=0;y<32;y++)for(let x=0;x<40;x++){
  const src=(mirror?39-x:x)+40*(y+32*z),dst=x+40*(y+32*z);
  const value=a[src]*(1-mix)+b[src]*mix;out[dst]=Math.round(value*(1-wrap)+frames[0][src]*wrap);
 }return out;
}
